import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create the plane geometry
  const geometry = new THREE.PlaneGeometry(3.2, 0.5);

  // Load the brushed metal texture
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 0.95,
  });

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(
    config.scenePosition?.[0] ?? 0,
    config.scenePosition?.[1] ?? 0,
    config.scenePosition?.[2] ?? 0
  );

  // Create subtle divider line at bottom (thin plane)
  const dividerGeometry = new THREE.PlaneGeometry(3.2, 0.01);
  const dividerMaterial = new MeshBasicNodeMaterial({
    color: 0x16161d,
    transparent: true,
    opacity: 0.15,
  });
  const divider = new THREE.Mesh(dividerGeometry, dividerMaterial);
  divider.position.z = 0.01;
  divider.position.y = -0.25;
  mesh.add(divider);

  // Interaction state
  const state = {
    isHovering: false,
    originalY: mesh.position.y,
  };

  // Timeline references for cleanup
  const timelines = [];

  // Hover handler: rise-in effect (subtle, 0.15 scene units)
  const onHover = () => {
    if (state.isHovering) return;
    state.isHovering = true;

    const tl = gsap.timeline();
    tl.to(
      mesh.position,
      {
        y: state.originalY + 0.15,
        duration: 0.5,
        ease: 'power3.out',
      },
      0
    );
    tl.to(
      material,
      {
        opacity: 1.0,
        duration: 0.3,
      },
      0
    );
    timelines.push(tl);
  };

  // Unhover handler: settle back
  const onUnhover = () => {
    if (!state.isHovering) return;
    state.isHovering = false;

    const tl = gsap.timeline();
    tl.to(
      mesh.position,
      {
        y: state.originalY,
        duration: 0.7,
        ease: 'power4.out',
        overwrite: 'auto',
      },
      0
    );
    tl.to(
      material,
      {
        opacity: 0.95,
        duration: 0.4,
      },
      0
    );
    timelines.push(tl);
  };

  // Click handler: press-down effect + emit event
  const onClick = () => {
    const tl = gsap.timeline();

    // Press scale
    tl.to(
      mesh.scale,
      {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      },
      0
    );

    // Release back
    tl.to(
      mesh.scale,
      {
        x: 1.0,
        y: 1.0,
        duration: 0.3,
        ease: 'power4.out',
      },
      0.12
    );

    timelines.push(tl);

    // Emit selection event
    ctx.emit('hub-collection.select', {
      itemId: config.itemId || 'collection-row',
    });
  };

  // Attach handlers
  if (!mesh.userData.handlers) {
    mesh.userData.handlers = {};
  }
  mesh.userData.handlers.onHover = onHover;
  mesh.userData.handlers.onUnhover = onUnhover;
  mesh.userData.handlers.onClick = onClick;

  // Cleanup
  mesh.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    geometry.dispose();
    dividerGeometry.dispose();
    material.dispose();
    dividerMaterial.dispose();
  };

  return mesh;
}
